import { Group, Mesh, BoxGeometry, PlaneGeometry, Color, MathUtils, DirectionalLight, ClampToEdgeWrapping, SRGBColorSpace } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = config?.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#12121a' }],
  };

  const root = new Group();
  root.name = 'filmstrip-carousel';

  const disposables = { geometries: [], materials: [], textures: [] };

  // ---------- STAGE BACKDROP ----------
  const stopA = new Color(colors.gradientStops?.[0]?.hex ?? '#0b0b10');
  const stopB = new Color(colors.gradientStops?.[1]?.hex ?? '#12121a');
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(
    vec3(stopA.r, stopA.g, stopA.b),
    vec3(stopB.r, stopB.g, stopB.b),
    uv().y
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.geometries.push(backdropGeo);
  disposables.materials.push(backdropMat);

  // ---------- LIGHTS (rim only — ambient+key provided by scene) ----------
  const rim = new DirectionalLight(new Color(colors.accent), 0.7);
  rim.position.set(-3, 2, 4);
  root.add(rim);
  const rimFill = new DirectionalLight(new Color('#ffffff'), 0.6);
  rimFill.position.set(2, -1, 5);
  root.add(rimFill);

  // ---------- CONTACT SHADOW ----------
  const shadowGeo = new PlaneGeometry(6.5, 2.2, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.45 });
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = mix(0.5, 0.0, uv().x.distance(0.5).add(uv().y.distance(0.5)).clamp(0, 1));
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -1.9, 0.2);
  root.add(shadowPlane);
  disposables.geometries.push(shadowGeo);
  disposables.materials.push(shadowMat);

  // ---------- FILMSTRIP ----------
  const stripGroup = new Group();
  stripGroup.rotation.y = MathUtils.degToRad(-18);
  root.add(stripGroup);

  const pitch = 1.85;
  const cardW = 1.6, cardH = 1.0, cardD = 0.05;
  const focusedIndex = 2;
  const captions = ['NA-01 MERIDIAN', 'NA-02 NOCTURNE', 'NA-03 SIGNAL', 'NA-04 VANTAGE', 'NA-05 ARCHIVE'];
  const inkColor = new Color(colors.ink);
  const accentColor = new Color(colors.accent);
  const paperColor = new Color(colors.paper);

  const frameMat = new MeshPhysicalNodeMaterial({
    color: inkColor, roughness: 0.5, metalness: 0.55, clearcoat: 0.2,
  });
  disposables.materials.push(frameMat);

  const cardGroups = [];
  const cardMats = [];
  const captionTexts = [];
  const uvOffsets = [
    { off: [0.0, 0.0], rep: 0.62 },
    { off: [0.16, 0.08], rep: 0.58 },
    { off: [0.3, 0.04], rep: 0.6 },
    { off: [0.08, 0.22], rep: 0.55 },
    { off: [0.22, 0.14], rep: 0.6 },
  ];

  for (let i = 0; i < 5; i++) {
    const isFocused = i === focusedIndex;
    const cardGroup = new Group();
    const x = (i - focusedIndex) * pitch;
    cardGroup.position.set(x, 0, 0);
    cardGroup.scale.setScalar(isFocused ? 1.0 : 0.92);
    if (isFocused) {
      cardGroup.rotation.y = MathUtils.degToRad(18); // cancel strip rotation, face camera
    }

    const cardMat = new MeshPhysicalNodeMaterial({
      color: new Color(colors.surface),
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      transparent: true,
      opacity: isFocused ? 1.0 : Math.max(0.55, 1.0 - Math.abs(i - focusedIndex) * 0.22),
    });
    cardMats.push(cardMat);
    disposables.materials.push(cardMat);

    const geo = new BoxGeometry(cardW, cardH, cardD);
    disposables.geometries.push(geo);
    const materials = [frameMat, frameMat, frameMat, frameMat, cardMat, frameMat];
    const cardMesh = new Mesh(geo, materials);
    cardGroup.add(cardMesh);

    // caption below each card
    const captionColor = isFocused ? colors.accent : colors.paper;
    const captionOpacityColor = isFocused ? '#ff2a38' : '#8a8a92';
    const capText = ctx.fontAtlas.createText(captions[i], {
      fontSize: 18,
      color: captionOpacityColor,
      align: 'center',
      letterSpacingPx: 1.4,
    });
    capText.position.set(0, -cardH / 2 - 0.25, 0.03);
    cardGroup.add(capText);
    captionTexts.push(capText);

    if (isFocused) {
      const underlineGeo = new PlaneGeometry(1.6, 0.035);
      const underlineMat = new MeshStandardNodeMaterial({
        color: accentColor,
        emissive: accentColor,
        emissiveIntensity: 1.3,
        roughness: 0.5,
        metalness: 0.1,
      });
      const underline = new Mesh(underlineGeo, underlineMat);
      underline.position.set(0, -cardH / 2 - 0.1, 0.03);
      cardGroup.add(underline);
      disposables.geometries.push(underlineGeo);
      disposables.materials.push(underlineMat);
    }

    stripGroup.add(cardGroup);
    cardGroups.push(cardGroup);
  }

  // ---------- TEXTURE LOAD (async, deferred assignment) ----------
  ctx.textureLoader.loadTexture(config.imageUrl).then((baseTex) => {
    cardMats.forEach((mat, i) => {
      const tex = baseTex.clone();
      tex.needsUpdate = true;
      tex.wrapS = ClampToEdgeWrapping;
      tex.wrapT = ClampToEdgeWrapping;
      tex.colorSpace = SRGBColorSpace;
      const { off, rep } = uvOffsets[i];
      tex.repeat.set(rep, rep);
      tex.offset.set(off[0], off[1]);
      mat.map = tex;
      mat.needsUpdate = true;
      disposables.textures.push(tex);
    });
  }).catch(() => {});

  // ---------- HEADLINE / BODY TEXT ----------
  const headline = ctx.fontAtlas.createText('The collection', {
    fontSize: 68,
    color: colors.paper,
    align: 'left',
  });
  headline.position.set(-2.6, 1.5, 0);
  root.add(headline);

  const body = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26,
    color: colors.paper,
    align: 'left',
  });
  body.position.set(-2.6, -1.5, 0);
  root.add(body);

  // ---------- ENTRANCE MOTION (weighted-settle, staggered) ----------
  const tl = gsap.timeline();
  cardGroups.forEach((cg, i) => {
    const targetScale = cg.scale.x;
    cg.scale.setScalar(targetScale * 0.85);
    cg.position.y -= 0.15;
    tl.to(cg.scale, {
      x: targetScale * 1.04, y: targetScale * 1.04, z: targetScale * 1.04,
      duration: 0.55, ease: 'power3.out',
    }, i * 0.08)
      .to(cg.scale, {
        x: targetScale, y: targetScale, z: targetScale,
        duration: 0.35, ease: 'power4.out',
      }, i * 0.08 + 0.55)
      .to(cg.position, {
        y: cg.position.y + 0.15, duration: 0.7, ease: 'power3.out',
      }, i * 0.08);
  });

  // ---------- CINEMATIC PRIMITIVES ----------
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(stripGroup, { ...(prim.params ?? {}), trigger: prim.trigger });
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------- EVENT HANDLERS ----------
  root.userData.handlers = {};

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    tl.kill();
    primitiveHandles.forEach((h) => h?.cleanup?.());
    disposables.geometries.forEach((g) => g.dispose());
    disposables.materials.forEach((m) => m.dispose());
    disposables.textures.forEach((t) => t.dispose());
    captionTexts.forEach((t) => {
      t.traverse?.((c) => {
        c.geometry?.dispose?.();
        c.material?.dispose?.();
      });
    });
    headline.traverse?.((c) => {
      c.geometry?.dispose?.();
      c.material?.dispose?.();
    });
    body.traverse?.((c) => {
      c.geometry?.dispose?.();
      c.material?.dispose?.();
    });
  };

  return root;
}
